export const OBJ_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/obj-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getObjStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(OBJ_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
